          const form=new window.FormData();form.append('file',file,file.name||('Screenshot.'+(file.type==='image/png'?'png':'jpg')));
          form.append('metadata',JSON.stringify({expectedRevision:plan.revision,definitionId:plan.definitionId,rowId:row.id,parentId:row.parentId||null,operation:row.name,sequence:ordered(plan.operations).find(x=>x.o.id===row.id).seq}));
