      if(panel.matches(':popover-open')){dismissOptions(true);return;}
      dismissOptions();const abort=new AbortController();
      dismissOptions=(restore=false)=>{abort.abort();if(panel.isConnected&&panel.matches(':popover-open'))panel.hidePopover();button.setAttribute('aria-expanded','false');if(restore&&button.isConnected)button.focus();dismissOptions=()=>{};};
      panel.showPopover();button.setAttribute('aria-expanded','true');
