      panel.style.left=Math.max(8,Math.min(anchor.left-size.width-6,window.innerWidth-size.width-8))+'px';
      panel.style.top=Math.max(8,Math.min(anchor.bottom+3,window.innerHeight-size.height-8))+'px';
      const outside=e=>{if(!panel.contains(e.target)&&!button.contains(e.target))dismissOptions();};
      document.addEventListener('pointerdown',outside,{capture:true,signal:abort.signal});
      document.addEventListener('focusin',outside,{signal:abort.signal});
      const observer=new MutationObserver(()=>{if(!button.isConnected)dismissOptions();});observer.observe(document.body,{childList:true,subtree:true});abort.signal.addEventListener('abort',()=>observer.disconnect(),{once:true});
      document.addEventListener('keydown',e=>{
        if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dismissOptions(true);return;}
        if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;
        const items=[...panel.querySelectorAll('button:not(:disabled)')];if(!items.length)return;
        e.preventDefault();const at=items.indexOf(document.activeElement);items[e.key==='Home'?0:e.key==='End'?items.length-1:(at+(e.key==='ArrowUp'?-1:1)+items.length)%items.length].focus();
      },{capture:true,signal:abort.signal});
      window.addEventListener('resize',()=>dismissOptions(),{signal:abort.signal});
      window.addEventListener('scroll',e=>{if(panel.contains(e.target))return;const now=button.getBoundingClientRect();if(now.x!==anchor.x||now.y!==anchor.y)dismissOptions();},{capture:true,signal:abort.signal});
      panel.addEventListener('toggle',()=>{if(!panel.matches(':popover-open'))dismissOptions();},{signal:abort.signal});
